//! Strongly typed identifiers for every persisted entity.
//!
//! Every id is a UUID so that ids generated by different clients during
//! collaboration cannot collide. Newtypes prevent mixing up node and style ids
//! at compile time; the JSON representation is the canonical hyphenated UUID
//! string.

use std::fmt;

use serde::{Deserialize, Serialize};
use uuid::Uuid;

macro_rules! id_type {
    ($(#[$meta:meta])* $name:ident) => {
        $(#[$meta])*
        #[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
        #[serde(transparent)]
        pub struct $name(pub Uuid);

        impl $name {
            /// Generates a new random id.
            pub fn new_v4() -> Self {
                Self(Uuid::new_v4())
            }

            /// Wraps an existing UUID.
            pub fn from_uuid(uuid: Uuid) -> Self {
                Self(uuid)
            }

            /// Wraps a raw 128 bit value (useful for deterministic tests).
            pub fn from_u128(value: u128) -> Self {
                Self(Uuid::from_u128(value))
            }

            /// Returns the inner UUID.
            pub fn as_uuid(&self) -> Uuid {
                self.0
            }
        }

        impl fmt::Display for $name {
            fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
                write!(f, "{}", self.0)
            }
        }

        impl fmt::Debug for $name {
            fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
                write!(f, "{}({})", stringify!($name), self.0)
            }
        }

        impl std::str::FromStr for $name {
            type Err = uuid::Error;

            fn from_str(value: &str) -> Result<Self, Self::Err> {
                Uuid::parse_str(value).map(Self)
            }
        }

        impl From<Uuid> for $name {
            fn from(value: Uuid) -> Self {
                Self(value)
            }
        }
    };
}

id_type!(
    /// A node in a page.
    NodeId
);
id_type!(
    /// A page.
    PageId
);
id_type!(
    /// A shared paint, text or effect style.
    StyleId
);
id_type!(
    /// A component definition (the node carrying the definition is referenced
    /// separately).
    ComponentId
);
id_type!(
    /// A component set (variant container).
    ComponentSetId
);
id_type!(
    /// A variable.
    VariableId
);
id_type!(
    /// A variable collection.
    CollectionId
);
id_type!(
    /// A variable mode inside a collection.
    ModeId
);
id_type!(
    /// An image or font asset.
    AssetId
);
id_type!(
    /// A prototype interaction.
    InteractionId
);
id_type!(
    /// A prototype flow.
    FlowId
);
id_type!(
    /// A document (file).
    DocumentId
);

/// Convenience alias used by APIs that accept any entity id.
pub trait EntityId: Copy + fmt::Debug + fmt::Display + Eq + std::hash::Hash {}

impl EntityId for NodeId {}
impl EntityId for PageId {}
impl EntityId for StyleId {}
impl EntityId for ComponentId {}
impl EntityId for VariableId {}
impl EntityId for AssetId {}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn ids_are_stable_strings() {
        let id = NodeId::from_u128(0x1234_5678_9abc_def0_1234_5678_9abc_def0);
        let text = id.to_string();
        assert_eq!(text, "12345678-9abc-def0-1234-56789abcdef0");
        let parsed: NodeId = text.parse().unwrap();
        assert_eq!(parsed, id);
    }

    #[test]
    fn ids_serialize_transparently() {
        let id = PageId::new_v4();
        let json = serde_json::to_string(&id).unwrap();
        assert!(json.starts_with('"'));
        let back: PageId = serde_json::from_str(&json).unwrap();
        assert_eq!(back, id);
    }
}
